BEGIN;
CREATE TABLE ai.systems (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, name text NOT NULL, intended_purpose text NOT NULL, owner_user_id uuid REFERENCES identity.users(id), ai_act_role text, classification text, status core.record_status NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai.models (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), system_id uuid NOT NULL REFERENCES ai.systems(id) ON DELETE CASCADE, provider_id uuid REFERENCES core.providers(id), model_name text NOT NULL, model_version text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(system_id,model_name,model_version));
CREATE TABLE ai.decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, system_id uuid NOT NULL REFERENCES ai.systems(id), model_id uuid REFERENCES ai.models(id), purpose text NOT NULL, subject_type text, subject_id uuid, input_hash text, output jsonb NOT NULL, policy_result jsonb NOT NULL DEFAULT '{}'::jsonb, human_review_required boolean NOT NULL DEFAULT false, correlation_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai.policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, policy_key text NOT NULL, version integer NOT NULL CHECK(version>0), definition jsonb NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(tenant_id,policy_key,version));
COMMIT;
